INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (172, 'registrarEventoWorkflow', 'Grava um evento na trilha de auditoria do workflow (usado pelo app para confirmar/desfazer modelo). Params: cicloId, tipo, crId, driverId, gestorId (0 = NULL), evento, statusDe, statusPara, comentario, autor, origem, agora', 'SQL', 'INSERT INTO WORKFLOW_AUDITORIA (CICLO_ID, TIPO, CR_ID, DRIVER_ID, GESTOR_ID, EVENTO, STATUS_DE, STATUS_PARA, COMENTARIO, AUTOR, ORIGEM, CRIADO_EM)
VALUES ({{cicloId}}, ''{{tipo}}'', NULLIF({{crId}}, 0), NULLIF({{driverId}}, 0), NULLIF({{gestorId}}, 0), ''{{evento}}'', ''{{statusDe}}'', ''{{statusPara}}'', ''{{comentario}}'', ''{{autor}}'', ''{{origem}}'', ''{{agora}}'')', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
